          ) : (
            <Button
              type="submit"
              size="icon-xs"
              disabled={!input.trim()}
              aria-label="Send"
              className="absolute right-4 bottom-4"
            >
              <IconArrowUp className="size-4" />
            </Button>
          )}
        </form>
      </motion.div>
    </motion.aside>
  );
}

